customize.css:
:root{--navy:#0b1d51;--pink:#d1124f;--line:#e6e9f4;--tint:#f6f8f7;--sans:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;--script:"Snell Roundhand","Apple Chancery","Segoe Script","Brush Script MT",cursive}
body{overflow-x:hidden}
.wrap{padding:0 1.25rem 0}
a{color:var(--pink)}
.topbar{background:#0a1647;color:#fff}
.topbar-in{max-width:1200px;margin:0 auto;padding:.5rem 1.25rem;display:flex;align-items:center;gap:1.1rem}
.topbar a{display:inline-flex;align-items:center;color:#fff;text-decoration:none}
.topbar a span{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.topbar img.icon{height:26px;width:auto;border-radius:0}
.topbar img[src*="3tv"]{height:30px}
.topbar-text{order:2;font:italic 1rem Georgia,serif;white-space:nowrap}
.topbar a:last-of-type{order:3;margin-left:auto}
header.site{border:0;margin:0;padding:1.1rem 0 .6rem;align-items:center;gap:1.5rem;flex-wrap:wrap}
img.logo{height:auto;width:min(300px,62vw);border-radius:0;mix-blend-mode:multiply}
header.site nav{display:flex;flex-wrap:wrap;justify-content:flex-end;align-items:center;gap:.4rem 1.35rem}
header.site nav a{margin:0;color:var(--navy);font:700 .74rem var(--sans);text-transform:uppercase;letter-spacing:.03em}
header.site nav a[href$="archive/"],header.site nav a[href$="tags/"],header.site nav a[href$="feed.xml"],header.site nav a[href$="about/"],header.site nav a[href$="contact/"],header.site nav a[href$="media/"]{display:none}
header.site nav a[href$="/search/"]{color:var(--pink)}
.home{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);grid-template-rows:repeat(4,auto) 1fr;column-gap:2.2rem;align-items:start;margin:0 0 1.4rem}
.home h1{grid-column:1;font:700 clamp(2.1rem,4.7vw,3.6rem)/1.08 Georgia,"Times New Roman",serif;color:var(--navy);margin:1rem 0 .7rem}
.home h1 em{font:400 1.06em/1 var(--script);color:var(--pink)}
.home>p:nth-child(2){grid-column:1;font-size:1.15rem;line-height:1.6;color:var(--navy);margin:.2rem 0 1rem}
.home>p:nth-child(3){grid-column:1;margin:.4rem 0 .5rem}
.home>p:nth-child(3) a{display:inline-block;background:var(--navy);color:#fff;padding:.95rem 1.5rem;border-radius:8px;font:700 .95rem var(--sans);text-transform:uppercase;letter-spacing:.02em;text-decoration:none}
.home>p:nth-child(4){grid-column:1;font:600 .95rem var(--sans);color:var(--pink);margin:0 0 1rem}
.home>p:nth-child(5){grid-column:2;grid-row:1/span 5;margin:0}
.home>p:nth-child(5) img{display:block;width:100%;aspect-ratio:16/11;object-fit:cover;object-position:60% 25%;border-radius:14px;-webkit-mask-image:linear-gradient(to right,transparent 0,#000 16%);mask-image:linear-gradient(to right,transparent 0,#000 16%)}
.home>ul{grid-column:1/-1;grid-row:6;list-style:none;padding:0;margin:1.2rem 0 0;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:.7rem}
.home>ul li,.home-after>ul li{position:relative;margin:0;text-align:center;font:.8rem/1.45 var(--sans);color:#4b5578}
.home>ul li{border:1px solid var(--line);border-radius:10px;padding:.85rem .4rem 1rem;background:#fff}
.home>ul li img{display:block;width:84px;height:auto;margin:0 auto .55rem;border-radius:0;mix-blend-mode:multiply}
.home>ul li a{display:block;color:var(--navy);font:700 .78rem var(--sans);text-transform:uppercase;text-decoration:none;margin-bottom:.35rem}
.home>ul li a::after{content:"";position:absolute;inset:0}
.home>h2{grid-column:1;grid-row:7;margin:1.8rem 0 .8rem;font:700 1.25rem var(--sans);text-transform:uppercase;letter-spacing:.02em;color:var(--navy)}
.home>h2::before{content:"✦ ";color:var(--pink)}
.home>p:nth-child(8){grid-column:2;grid-row:7;justify-self:end;align-self:end;margin:0 0 .8rem;font:700 .85rem var(--sans);text-transform:uppercase}
.home>p:nth-child(8) a{text-decoration:none}
ul.posts.cards{grid-template-columns:repeat(5,minmax(0,1fr));gap:.9rem}
ul.posts.cards li{position:relative;display:flex;flex-direction:column;margin:0;padding:0 0 3rem;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:#fff}
ul.posts.cards .thumb{display:block;aspect-ratio:4/3;overflow:hidden;background:var(--tint)}
ul.posts.cards .thumb img{width:100%;height:100%;object-fit:cover;border-radius:0}
ul.posts.cards h2{margin:.75rem .85rem .35rem;font:700 .92rem/1.3 var(--sans)}
ul.posts.cards li:not(:has(.thumb)){background:linear-gradient(var(--tint),var(--tint)) top/100% 6.6rem no-repeat #fff}
ul.posts.cards li:not(:has(.thumb)) h2{margin-top:7.3rem}
ul.posts.cards h2 a{color:var(--navy)}
ul.posts.cards h2 a::after{content:"";position:absolute;inset:0}
ul.posts.cards p{margin:0 .85rem;font:.76rem/1.45 var(--sans);color:#56608a;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
ul.posts.cards .meta{position:absolute;left:.85rem;bottom:.8rem;margin:0;font:700 .66rem var(--sans);text-transform:uppercase;letter-spacing:.02em;color:var(--navy)}
ul.posts.cards .meta .tag{display:none}
ul.posts.cards li::after{content:"Read Deal →";position:absolute;right:.85rem;bottom:.8rem;font:700 .7rem var(--sans);color:var(--pink)}
ul.posts.cards li:has(a[href*="hot-deal"])::before,ul.posts.cards li:has(a[href*="/free/"])::before,ul.posts.cards li:has(a[href*="/expired/"])::before{position:absolute;z-index:2;top:.6rem;left:.6rem;padding:.2rem .5rem;border-radius:4px;font:700 .62rem var(--sans);letter-spacing:.03em;color:#fff}
ul.posts.cards li:has(a[href*="/free/"])::before{content:"FREE";background:var(--navy)}
ul.posts.cards li:has(a[href*="hot-deal"])::before{content:"HOT DEAL";background:var(--pink)}
ul.posts.cards li:has(a[href*="/expired/"])::before{content:"EXPIRED";background:#6b7280}
.pagination{font-family:var(--sans)}
.pagination a{color:var(--pink);font-weight:700}
.home-after{display:grid;grid-template-columns:150px minmax(0,1fr) minmax(0,1.5fr);gap:.1rem 1.4rem;margin:2.2rem 0 0;align-items:start}
.home-after>ul{grid-column:1/-1;list-style:none;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem;margin:0 0 1.2rem;padding:1.2rem;background:var(--tint);border-radius:12px}
.home-after>ul li{margin:0}
.home-after>ul li img{display:block;width:46px;height:46px;margin:0 auto .5rem;border-radius:0}
.home-after>ul li strong{display:block;color:var(--navy);font-size:.85rem}
.home-after h2{margin:0 0 .5rem;font:700 .95rem var(--sans);text-transform:uppercase;color:var(--navy)}
.home-after>h2:nth-child(2){grid-column:2;grid-row:2}
.home-after>p:nth-child(3){grid-column:1;grid-row:2/span 3;margin:0}
.home-after>p:nth-child(3) img{display:block;width:100%;height:auto;border-radius:12px}
.home-after>p:nth-child(4){grid-column:2;font:.9rem/1.55 var(--sans);margin:0 0 .6rem}
.home-after>p:nth-child(5){grid-column:2;font:700 .8rem var(--sans);text-transform:uppercase;margin:0}
.home-after>p:nth-child(5) a{text-decoration:none;display:inline-block;background:var(--navy);color:#fff;padding:.6rem 1rem;border-radius:6px}
.home-after>h2:nth-child(6){grid-column:3;grid-row:2;text-align:center}
.home-after>p:nth-child(7){grid-column:3;margin:.3rem 0 .4rem}
.home-after>p:nth-child(7) a{display:block;text-align:center;background:var(--pink);color:#fff;padding:.8rem;border-radius:8px;font:700 .95rem var(--sans);text-transform:uppercase;text-decoration:none}
.home-after>p:nth-child(8){grid-column:3;text-align:center;font:600 .8rem var(--sans);margin:0}
.home-after>h2:nth-child(9){grid-column:1/-1;margin:1.6rem 0 .3rem;text-align:center;color:#56608a;font-size:.8rem;letter-spacing:.08em}
.home-after>p:nth-child(10){grid-column:1/-1;display:flex;justify-content:center;align-items:center;gap:1.4rem;flex-wrap:wrap;margin:0}
.home-after>p:nth-child(10) img{height:96px;width:auto;border-radius:4px}
footer.site{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem 1.5rem;margin:2.4rem calc(50% - 50vw) 0;padding:1rem max(1.25rem,calc(50vw - 600px));background:var(--navy);border:0;color:#fff;font-size:0}
footer.site a{color:#fff;font:700 .72rem var(--sans);text-transform:uppercase;letter-spacing:.04em;text-decoration:none}
footer.site a span{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
footer.site img.icon{height:22px;width:auto;border-radius:0;display:block}
footer.site .foot-text{order:2;margin:0 auto;font:.74rem var(--sans);color:#c9d2f2}
footer.site a:has(img){order:3}
footer.site a:has(img)+a:has(img){margin-left:-.4rem}
@media (max-width:1000px){.home{grid-template-columns:minmax(0,1fr)}.home>p:nth-child(5){grid-column:1;grid-row:auto;order:-1}.home>ul{grid-row:auto;grid-template-columns:repeat(4,minmax(0,1fr))}.home>h2,.home>p:nth-child(8){grid-row:auto}.home>p:nth-child(8){grid-column:1;justify-self:start}ul.posts.cards{grid-template-columns:repeat(3,minmax(0,1fr))}.home-after{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.home-after>ul{grid-template-columns:repeat(2,minmax(0,1fr))}.home-after>p:nth-child(3){grid-row:auto;grid-column:1}.home-after>h2:nth-child(2),.home-after>p:nth-child(4),.home-after>p:nth-child(5){grid-column:2}.home-after>h2:nth-child(6),.home-after>p:nth-child(7),.home-after>p:nth-child(8){grid-column:1/-1}.topbar-text{display:none}}
@media (max-width:640px){.home>ul{grid-template-columns:repeat(2,minmax(0,1fr))}ul.posts.cards{grid-template-columns:repeat(2,minmax(0,1fr))}header.site nav{justify-content:flex-start}.home-after>p:nth-child(3){grid-column:1/-1}.home-after>h2:nth-child(2),.home-after>p:nth-child(4),.home-after>p:nth-child(5){grid-column:1/-1}}

article{max-width:46rem;margin:1.5rem auto 0}
article h1{font:700 clamp(1.7rem,3.4vw,2.4rem)/1.2 Georgia,serif;color:var(--navy)}
article .meta{font-family:var(--sans)}
article .meta a{color:var(--pink)}
article a{overflow-wrap:anywhere}
.post-nav{max-width:46rem;margin-inline:auto}
